-- Sostituisce il set segnaposto con i primi set reali scelti tramite il catalogatore locale.
-- Gli asset corrispondenti vivono in R2 sotto carte/designs/<set>/<file>.
DELETE FROM carte_trade_items WHERE carta_definizione_id IN (SELECT cd.id FROM carte_definizioni cd JOIN carte_designs d ON d.id = cd.design_id JOIN carte_sets s ON s.id = d.set_id WHERE s.slug IN ('placeholder', 'simboli', 'settembre', 'maggio', 'luglio', 'meme', 'fuochetto'));
DELETE FROM carte_possesso WHERE carta_definizione_id IN (SELECT cd.id FROM carte_definizioni cd JOIN carte_designs d ON d.id = cd.design_id JOIN carte_sets s ON s.id = d.set_id WHERE s.slug IN ('placeholder', 'simboli', 'settembre', 'maggio', 'luglio', 'meme', 'fuochetto'));
DELETE FROM carte_definizioni WHERE design_id IN (SELECT d.id FROM carte_designs d JOIN carte_sets s ON s.id = d.set_id WHERE s.slug IN ('placeholder', 'simboli', 'settembre', 'maggio', 'luglio', 'meme', 'fuochetto'));
DELETE FROM carte_designs WHERE set_id IN (SELECT id FROM carte_sets WHERE slug IN ('placeholder', 'simboli', 'settembre', 'maggio', 'luglio', 'meme', 'fuochetto'));
DELETE FROM carte_sets WHERE slug IN ('placeholder', 'simboli', 'settembre', 'maggio', 'luglio', 'meme', 'fuochetto');
